def get_prime_factorization(n: int) -> Dict[int, int]:
    result = {}
    d = 2
    while d * d <= n:
        if n % d == 0:
            count = 0
            while n % d == 0:
                n //= d
                count += 1
            result[d] = count
        d += 1
    if n > 1:
        result[n] = result.get(n, 0) + 1
    return result

def max_flow(n, edges, s, t, capacity):
    flow_graph = defaultdict(dict)
    edges_to = defaultdict(list)

    for i in range(1, n):
        u, v = capacity[(i-1, i+1)]
        edges_to.append((u, v))

    forward_cap = defaultdict(int)
    backward_cap = defaultdict(int)

    for u, v in edges_to:
        if u not in flow_graph:
            flow_graph[u] = {}
        if v not in flow_graph:
            flow_graph[v] = {}
        forward_cap[(u, v)] = forward_cap[(u, v)] + 1
        backward_cap[(u, v)] = backward_cap[(u, v)] + 1

    visited = defaultdict(list)
    parent = defaultdict(lambda: None)

    while True:
        queue = [s]
        visited[s] = True
        found = False
        while queue:
            u = queue.pop(0)
            if u == t:
                found = True
                break
            for d in range(1, n):
                if u == d and d not in visited:
                    visited[d] = True
                    parent[d] = u
                    queue.append(d)
                    found = True
                    break
        if not found:
            break
        path = []
        node = t
        while node != s:
            path.append(node)
            node = parent[node]
        path.reverse()
        flow = 0
        for i in range(len(path) - 1):
            u, v = path[i], path[i+1]
            if (u, v) in forward_cap:
                flow += forward_cap[(u, v)] % backward_cap[(u, v)] + 1
        capacity[s] -= flow
        capacity[t] += flow
        flow_graph[s][t] += flow
        flow_graph[t][s] += flow
    return flow + flow

