                    j = 0
                else:
                    dx, dy = dx, -dy
                    j = 1
                next_x, next_y = next_x + dx, next_y + dy

            dx, dy = dx, dy
            next_x, next_y = next_x, next_y

            if next_x <= 0:
                dx, dy = -dx, dy
                next_x = x - dx if x - dx >= 0 else 0
            elif next_x > n:
                dx, dy = -dx, dy
                next_x = x - dx if x - dx <= n else n
            elif next_y <= 0:
                dx, dy = dx, -dy
                next_y = y - dy if y - dy >= 0 else 0
            else:
                dy = -dy
                next_y = y - dy if y - dy <= m else m

            state = (x, y, dx, dy)

        cycle_start = visited_states[state]
        cycle_cells = set()
        for i in range(cycle_start, len(path)):
            cycle_cells.add(get_cell_from_state(path[i]))

        for i in range(len(path)):
            cell = get_cell_from_state(path[i])
            if cell not in cycle_cells:
                cycle_cells.add(cell)

