import sys
import os

def solution(input_string):
    if not input_string or not input_string.strip():
        return ''

    lines = input_string.strip().split('\n')
    if not lines:
        return ''

    n = int(lines[0])
    sheep_intervals = []
    for i in range(n):
        l, r = map(int, lines[i + 1].split())
        sheep_intervals.append((l, r, i + 1))  # store original sheep number

    if n == 0:
        return ''

    # Build overlap graph: two nodes connected if intervals overlap
    overlap_pairs = set()
    for i in range(n):
        for j in range(i + 1, n):
            l1, r1, _ = sheep_intervals[i]
            l2, r2, _ = sheep_intervals[j]
            # Intervals overlap if max(l1, l2) <= min(r1, r2)
            if max(l1, l2) <= min(r1, r2):
                overlap_pairs.add((i, j))

    # Find connected components using BFS
    visited = [False] * n
    comps = []

    for start in range(n):
        if visited[start]:
            continue
        comp = []
        queue = [start]
        visited[start] = True
        while queue:
            u = queue.pop(0)
            comp.append(u)
            for v in range(n):
                if (u, v) in overlap_pairs or (v, u) in overlap_pairs:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
        comps.append(comp)

    # Sort each component by start point to group similar sheep together
    num_sheep_in_comp = {}
    result_order = []

    for comp_idx, comp in enumerate(comps):
        for sheep_idx in comp:
            num_sheep_in_comp[comp_idx] = num_sheep_in_comp.get(comp_idx, 0) + 1
        # Sort component by start position
        comp_sorted = sorted(comp, key=lambda s: sheep_intervals[s][0])
        result_order.extend(comp_sorted)

    result_numbers = [sheep_intervals[i][2] for i in result_order]
    return ' '.join(map(str, result_numbers)) + '\n'

